import {
  EventStatusEnum,
  EvidenceSourceEnum,
  PlanDecisionEnum,
  PlanStatusEnum,
  RiskLevelEnum,
  WorkEventInput,
  WorkEventResult,
  WorkEventsController,
} from '../src';
import { testClient } from './testClient.js';
import {
  expectHeadersToMatch,
  expectMatchingWithOptions,
  makeApiCall,
} from './testHelper.js';

describe('WorkEventsController', () => {
  let controller : WorkEventsController;

  beforeAll(() => {
    controller = new WorkEventsController(testClient);
  });

  it('should Test submitWorkEvent', async () => {
    const body: WorkEventInput = {
      text: 'PR #42 "Landing page" was merged and deployed. Client: Landing page is live and looks great, thank you Jean!',
      source: EvidenceSourceEnum.Github,
      title: 'Pull request #42 merged',
    };

    const response = await makeApiCall(() => controller.submitWorkEvent(body));

    expect(response.statusCode).toBe(201);

    const expectedHeaders = { 'Content-Type': ['application/json', true] };

    expectHeadersToMatch(response.headers, expectedHeaders);

    const expected: WorkEventResult = {
      eventId: 12,
      status: EventStatusEnum.Done,
      risk: RiskLevelEnum.Low,
      summary: 'PR #42 was merged and the client confirmed the landing page is live. I proposed Jean\'s $250.00 milestone.',
      plans: [
        {
          planId: 7,
          title: 'Jean Pierre · Landing page live',
          totalCents: 25000,
          decision: PlanDecisionEnum.Ask,
          status: PlanStatusEnum.NeedsApproval,
        }
      ],
    };

    expect(response.result).not.toBeNull();
    expectMatchingWithOptions(
      expected,
      response.result,
      { allowExtra: true, isOrdered: false, checkValues: false }
    );
  });

  it('should Test getWorkEvent', async () => {
    const eventId = 12;

    const response = await makeApiCall(() => controller.getWorkEvent(eventId));

    expect(response.statusCode).toBe(200);

    const expectedHeaders = { 'Content-Type': ['application/json', true] };

    expectHeadersToMatch(response.headers, expectedHeaders);

    const expected: WorkEventResult = {
      eventId: 12,
      status: EventStatusEnum.Done,
      risk: RiskLevelEnum.Low,
      summary: 'PR #42 was merged and the client confirmed the landing page is live.',
      plans: [
        {
          planId: 7,
          title: 'Jean Pierre · Landing page live',
          totalCents: 25000,
          decision: PlanDecisionEnum.Ask,
          status: PlanStatusEnum.Sent,
        }
      ],
    };

    expect(response.result).not.toBeNull();
    expectMatchingWithOptions(
      expected,
      response.result,
      { allowExtra: true, isOrdered: false, checkValues: false }
    );
  });
});
